window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5db3b544aa71cd0b"]={"versions": [{"id": "FIG-5db3b544aa71cd0b", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zustandsdiagramm zur Darstellung des beispielhaften Hochlaufs (Startup) und der Controller-Zustandsübergänge im AUTOSAR TTCAN Interface (<code>AUTOSAR_SWS_TTCANInterface</code>). Das Diagramm veranschaulicht die zeitliche Abfolge der Initialisierungs- und Synchronisationsphasen in Relation zu den Controller-Modi des CAN Interfaces (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Controller-Zustände (CanIf Controller States)</strong>:\n<ul class=\"fig-list\"><li><code>CANIF_CS_UNINIT</code>: Initialer, uninitialisierter Zustand.\n</li><li><code>CANIF_CS_STOPPED</code>: Zustand nach Abschluss der Basisinitialisierung; Controller ist gestoppt, aber betriebsbereit.\n</li><li><code>CANIF_CS_STARTED</code>: Vollständiger Betriebsmodus nach erfolgreicher Synchronisation.\n</li></ul>\n</li><li><strong>Prozessphasen / Ereignisse</strong>:\n<ul class=\"fig-list\"><li><code>Initialisation</code>: Phase der Initialisierung des TTCAN-Controllers.\n</li><li><code>Synchronisation according to ISO11898-4 [11]</code>: Zeitspanne zur Synchronisation des Controllers mit dem TTCAN-Kommunikationszyklus gemäß ISO 11898-4.\n</li><li>Trigger-/Ereignispfeile für Initialisierungsstart, Abschluss der Initialisierung (<code>finished</code>), Anforderung/Trigger für <code>STARTED</code> sowie Zustandswechsel.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das System beginnt im Zustand <code>CANIF_CS_UNINIT</code>. Ein eingehendes Signal stößt die Phase <code>Initialisation</code> an.\n</li><li>Mit dem Abschluss der Initialisierung (<code>finished</code>) wechselt der Controllerzustand von <code>CANIF_CS_UNINIT</code> zu <code>CANIF_CS_STOPPED</code>.\n</li><li>Im Zustand <code>CANIF_CS_STOPPED</code> wird die Phase <code>Synchronisation according to ISO11898-4 [11]</code> durch einen Trigger eingeleitet.\n</li><li>Nach erfolgreichem Durchlauf der Synchronisationsphase wechselt der Controllerzustand an der rechten Intervallgrenze in <code>CANIF_CS_STARTED</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verdeutlicht das normative Zusammenspiel zwischen den CanIf-Zuständen und den Hardware-/Protokollphasen des TTCAN-Controllers.\n</li><li>Der Wechsel in den Zustand <code>CANIF_CS_STARTED</code> darf erst nach erfolgreicher Synchronisation gemäß ISO 11898-4 erfolgen; während der Synchronisation verbleibt der Controller im Zustand <code>CANIF_CS_STOPPED</code>.\n</li><li>Die Literaturreferenz <code>[11]</code> verweist innerhalb des Dokuments auf den Standard ISO 11898-4.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1fdc16716093d778", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zustandsdiagramm zur Darstellung des beispielhaften Hochlaufs (Startup) und der Controller-Zustandsübergänge im AUTOSAR TTCAN Interface (<code>AUTOSAR_SWS_TTCANInterface</code>). Das Diagramm veranschaulicht die zeitliche Abfolge der Initialisierungs- und Synchronisationsphasen in Relation zu den Controller-Modi des CAN Interfaces (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Controller-Zustände (CanIf Controller States)</strong>:\n<ul class=\"fig-list\"><li><code>CANIF_CS_UNINIT</code>: Initialer, uninitialisierter Zustand.\n</li><li><code>CANIF_CS_STOPPED</code>: Zustand nach Abschluss der Basisinitialisierung; Controller ist gestoppt, aber betriebsbereit.\n</li><li><code>CANIF_CS_STARTED</code>: Vollständiger Betriebsmodus nach erfolgreicher Synchronisation.\n</li></ul>\n</li><li><strong>Prozessphasen / Ereignisse</strong>:\n<ul class=\"fig-list\"><li><code>Initialisation</code>: Phase der Initialisierung des TTCAN-Controllers.\n</li><li><code>Synchronisation according to ISO11898-4 [12]</code>: Zeitspanne zur Synchronisation des Controllers mit dem TTCAN-Kommunikationszyklus gemäß ISO 11898-4.\n</li><li>Trigger-/Ereignispfeile für Initialisierungsstart, Abschluss der Initialisierung (<code>finished</code>), Anforderung/Trigger für <code>STARTED</code> sowie Zustandswechsel.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das System beginnt im Zustand <code>CANIF_CS_UNINIT</code>. Ein eingehendes Signal stößt die Phase <code>Initialisation</code> an.\n</li><li>Mit dem Abschluss der Initialisierung (<code>finished</code>) wechselt der Controllerzustand von <code>CANIF_CS_UNINIT</code> zu <code>CANIF_CS_STOPPED</code>.\n</li><li>Im Zustand <code>CANIF_CS_STOPPED</code> wird die Phase <code>Synchronisation according to ISO11898-4 [12]</code> durch einen Trigger eingeleitet.\n</li><li>Nach erfolgreichem Durchlauf der Synchronisationsphase wechselt der Controllerzustand an der rechten Intervallgrenze in <code>CANIF_CS_STARTED</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verdeutlicht das normative Zusammenspiel zwischen den CanIf-Zuständen und den Hardware-/Protokollphasen des TTCAN-Controllers.\n</li><li>Der Wechsel in den Zustand <code>CANIF_CS_STARTED</code> darf erst nach erfolgreicher Synchronisation gemäß ISO 11898-4 erfolgen; während der Synchronisation verbleibt der Controller im Zustand <code>CANIF_CS_STOPPED</code>.\n</li><li>Die Literaturreferenz <code>[12]</code> verweist innerhalb des Dokuments auf den Standard ISO 11898-4.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-5db3b544aa71cd0b", "to": "FIG-1fdc16716093d778", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Textkasten für die Synchronisationsphase: Quellenverweis von <code>ISO11898-4 [11]</code> auf <code>ISO11898-4 [12]</code> aktualisiert.\n</li></ul>"}]};
